315	  protected readonly quickForm = new FormGroup({
316	    name: new FormControl('', { nonNullable: true }),
317	    amount: new FormControl('', { nonNullable: true }),
318	  });
319	
320	  constructor() {
321	    this.form.valueChanges.subscribe(() => this.error.set(''));
322	    this.quickForm.valueChanges.subscribe(() => this.quickError.set(''));
323	    effect(() => {
324	      const id = this.session.sheetId();
325	      this.session.loads();
326	      this.people.set([]);
327	      this.claims.set([]);
328	      this.rates.set([]);
329	      this.periods.set([]);
330	      this.statements.set([]);
331	      this.personError.set(null);
332	      this.patronError.set(null);
333	      this.reset();
334	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
335	      this.quickError.set('');
336	      if (id) void this.load(id);
337	    });
338	  }
339	
340	  private headers(): Record<string, string> {
341	    return { 'X-User': this.session.user() ?? '' };
342	  }
343	
344	  private url(sheet: string): string {
345	    return `/api/sheets/${encodeURIComponent(sheet)}/people`;
346	  }
347	
348	  private async load(sheet: string): Promise<void> {
349	    try {
350	      const [list, claims, rates, statements, periods] = await Promise.all([
351	        firstValueFrom(this.http.get<Person[]>(this.url(sheet), { headers: this.headers() })),
352	        firstValueFrom(this.http.get<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`, { headers: this.headers() })),
353	        firstValueFrom(this.http.get<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`, { headers: this.headers() })),
354	        firstValueFrom(this.http.get<StatementSummary[]>(`/api/sheets/${encodeURIComponent(sheet)}/statements`, { headers: this.headers() })),
355	        firstValueFrom(this.http.get<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { headers: this.headers() })),
356	      ]);
357	      if (this.session.sheetId() !== sheet) return;
358	      this.people.set(list);
359	      this.claims.set(claims);
360	      this.rates.set(rates);
361	      this.statements.set(statements);
362	      this.periods.set(periods);
363	    } catch {
364	      if (this.session.sheetId() === sheet) this.error.set('Could not load the people on this sheet.');
365	    }
366	  }
367	
368	  protected claimsOf(personId: number): Claim[] {
369	    return this.claimsByPerson().get(personId) ?? NO_CLAIMS;
370	  }
371	
372	  private claimedCents(personId: number): number {
373	    return this.claimsOf(personId).filter(this.counts).reduce((sum, c) => sum + cents(c.amount), 0);
374	  }
375	
376	  protected claimedOf(personId: number): string {
377	    return money(this.claimedCents(personId));
378	  }
379	
380	  protected ratesOf(grade: string): Rate[] {
381	    return this.ratesByGrade().get(grade) ?? NO_RATES;
382	  }
383	
384	  /** The person's rate on a date, of the grade in force for them then. */
385	  protected pctOnOf(personId: number): PctOn {
386	    return this.pctOnByPerson().get(personId) ?? NO_PCT;
387	  }
388	
389	  /** The person's grade in force on the sheet's today. */
390	  protected gradeOf(p: Person): string {
391	    const today = this.session.today();
392	    return today === null ? p.grade : gradeOn(p, today);
393	  }
394	
395	  /** The grade's rate in force on the sheet's today, or null when none is. */
396	  protected pctOf(grade: string): string | null {
397	    return this.pctByGrade().get(grade) ?? null;
398	  }
399	
400	  /**
401	   * The sum of the dues of their claims that count, each already rounded to cents; null (n/a) when
402	   * their grade has no rate in force today and none of those claims has a due fixed when settled or bound by a statement,
403	   * nor a due under another grade they had on its date.
404	   */
405	  private dueTotalCents(p: Person): number | null {
406	    const counted = this.claimsOf(p.id).filter(this.counts);
407	    const pctOn = this.pctOnOf(p.id);
408	    const floor = cents(this.session.floor());
409	    const late = this.session.late();
410	    const gradeToday = this.gradeOf(p);
411	    const fixed = (c: Claim) => c.settledDue !== null || (c.stated && c.statedDue !== null)
412	      || (gradeOn(p, c.date) !== gradeToday && claimDueCents(c, pctOn, floor, late) !== null);
413	    if (this.pctOf(gradeToday) === null && !counted.some(fixed)) return null;
414	    return counted.reduce((sum, c) => sum + (claimDueCents(c, pctOn, floor, late) ?? 0), 0);
415	  }
416	
417	  protected overdueOf(p: Person): Overdue {
418	    return this.overdueByPerson().get(p.id) ?? { count: 0, cents: 0 };
419	  }
420	
421	  /** Their due-total, or n/a. */
422	  protected dueTotalOf(p: Person): string {
423	    const total = this.dueTotalCents(p);
424	    return total === null ? NA : money(total);
425	  }
426	
427	  /** Their patrons' names, comma and space separated, sorted. */
428	  protected patronsOf(p: Person): string {
429	    return this.patronsOfPerson(p)
430	      .map((x) => x.name)
431	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
432	      .join(', ');
433	  }
434	
435	  /** Their patrons' due-totals added up, skipping n/a; 0.00 with no patrons. */
436	  protected backingOf(p: Person): string {
437	    return money(this.patronsOfPerson(p).reduce((sum, x) => sum + (this.dueTotalCents(x) ?? 0), 0));
438	  }
439	
440	  private patronsOfPerson(p: Person): Person[] {
441	    const byId = this.peopleById();
442	    return p.patronIds.map((id) => byId.get(id)).filter((x): x is Person => x !== undefined);
443	  }
444	
445	  /** The people who may be offered as the person's patron: everyone else on the sheet. */
446	  protected patronChoicesFor(p: Person): Person[] {
447	    return this.people().filter((x) => x.id !== p.id);
448	  }
449	
450	  protected clearPatronError(id: number): void {
451	    if (this.patronError()?.id === id) this.patronError.set(null);
452	  }
453	
454	  /** Name the person chosen in the select as the person's patron. */
455	  protected async addPatron(p: Person, select: HTMLSelectElement): Promise<void> {
456	    this.personError.set(null);
457	    this.patronError.set(null);
458	    const sheet = this.session.sheetId();
459	    if (!sheet) return;
460	    const patronId = Number(select.value);
461	    if (!select.value || !Number.isInteger(patronId)) {
462	      this.patronError.set({ id: p.id, message: 'Choose a patron.' });
463	      return;
464	    }
465	    if (patronId === p.id || p.patronIds.includes(patronId)) {
466	      this.patronError.set({ id: p.id, message: patronId === p.id ? 'A person cannot be their own patron.' : 'That patron is already named.' });
467	      return;
468	    }
469	    try {
470	      const saved = await firstValueFrom(
471	        this.http.post<Person>(`${this.url(sheet)}/${p.id}/patrons`, { patronId }, { headers: this.headers() }),
472	      );
473	      if (this.session.sheetId() !== sheet) return;
474	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
475	      select.value = '';
476	    } catch (e) {
477	      if (this.session.sheetId() !== sheet) return;
478	      this.patronError.set({
479	        id: p.id,
480	        message: e instanceof HttpErrorResponse && e.status === 409
481	          ? 'That patron is already named, or is the person themselves.'
482	          : 'Could not add that patron for ' + p.name + '.',
483	      });
484	    }
485	  }
486	
487	  protected statementOf(personId: number): StatementSummary | undefined {
488	    return this.statementByPerson().get(personId);
489	  }
490	
491	  /** The last statement's due-total: blank before any statement, n/a when it had none. */
492	  protected statedTotalOf(personId: number): string {
493	    const s = this.statementOf(personId);
494	    return s === undefined ? '' : (s.lastDueTotal ?? NA);
495	  }
496	
497	  /** Take a statement for the person, binding their counting claims to their dues now. */
498	  protected async takeStatement(p: Person): Promise<void> {
499	    this.personError.set(null);
500	    this.clearPatronError(p.id);
501	    const sheet = this.session.sheetId();
502	    if (!sheet) return;
503	    try {
504	      const taken = await firstValueFrom(
505	        this.http.post<StatementTaken>(`${this.url(sheet)}/${p.id}/statement`, null, { headers: this.headers() }),
506	      );
507	      if (this.session.sheetId() !== sheet) return;
508	      this.statements.update((list) => [...list.filter((s) => s.personId !== p.id), taken.summary]);
509	      const byId = new Map(taken.claims.map((c) => [c.id, c]));
510	      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
511	    } catch {
512	      if (this.session.sheetId() === sheet) this.personError.set({ id: p.id, message: 'Could not take a statement for ' + p.name + '.' });
513	    }
514	  }
515	
516	  protected clearPersonError(id: number): void {
517	    if (this.personError()?.id === id) this.personError.set(null);
518	  }
519	
520	  /** Retire the person from the date (blank: the sheet's today). */
521	  protected async retire(p: Person, date: string): Promise<void> {
522	    this.personError.set(null);
523	    this.clearPatronError(p.id);
524	    const sheet = this.session.sheetId();
525	    if (!sheet) return;
526	    const from = date.trim();
527	    if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
528	      this.personError.set({ id: p.id, message: 'Enter a date, or leave it blank for today.' });
529	      return;
530	    }
531	    try {
532	      const saved = await firstValueFrom(
533	        this.http.post<Person>(`${this.url(sheet)}/${p.id}/retire`, { from: from || null }, { headers: this.headers() }),
534	      );
535	      if (this.session.sheetId() !== sheet) return;
536	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
537	    } catch {
538	      if (this.session.sheetId() === sheet) this.personError.set({ id: p.id, message: 'Could not retire ' + p.name + '.' });
539	    }
540	  }
541	
542	  /** Put the person on hold, or take them off it when held. */
543	  protected async toggleHold(p: Person): Promise<void> {
544	    this.personError.set(null);
545	    this.clearPatronError(p.id);
546	    const sheet = this.session.sheetId();
547	    if (!sheet) return;
548	    try {
549	      const saved = await firstValueFrom(
550	        this.http.post<Person>(`${this.url(sheet)}/${p.id}/hold`, null, { headers: this.headers() }),
551	      );
552	      if (this.session.sheetId() !== sheet) return;
553	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
554	    } catch {
555	      if (this.session.sheetId() === sheet) {
556	        this.personError.set({ id: p.id, message: 'Could not ' + (p.held ? 'release ' : 'hold ') + p.name + '.' });
557	      }
558	    }
559	  }
560	
561	  /** Put a set rate in place of the grade's old one from the same date. */
562	  protected rateSaved(rate: Rate): void {
563	    this.rates.update((list) => [...list.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
564	  }
565	
566	  /** Put an added period in its place by from-date, or a closed or reopened one in its place. */
567	  protected periodSaved(period: Period): void {
568	    this.periods.update((list) =>
569	      [...list.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : 1)),
570	    );
571	  }
572	
573	  /** Put an added claim first, or an edited one in its place. */
574	  protected claimSaved(claim: Claim): void {
575	    this.claims.update((list) =>
576	      list.some((c) => c.id === claim.id) ? list.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...list],
577	    );
578	  }
579	
580	  private reset(): void {
581	    this.editingId.set(null);
582	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' }, { emitEvent: false });
583	    this.error.set('');
584	  }
585	
586	  protected edit(p: Person): void {
587	    this.personError.set(null);
588	    this.editingId.set(p.id);
589	    this.editingVersion = p.version;
590	    this.form.setValue({ name: p.name, grade: this.gradeOf(p), gradeFrom: '' }, { emitEvent: false });
591	    this.error.set('');
592	  }
593	
594	  protected cancel(): void {
595	    this.reset();
596	  }
597	
598	  protected async save(): Promise<void> {
599	    if (this.saving) return;
600	    this.error.set('');
601	    const sheet = this.session.sheetId();
602	    if (!sheet) return;
603	    const raw = this.form.getRawValue();
604	    const name = raw.name.trim();
605	    const grade = raw.grade;
606	    const gradeFrom = raw.gradeFrom.trim() || null;
607	    if (!name) {
608	      this.error.set('Enter a name.');
609	      return;
610	    }
611	    if (!this.grades.includes(grade)) {
612	      this.error.set('Choose a grade.');
613	      return;
614	    }
615	    const id = this.editingId();
616	    this.saving = true;
617	    try {
618	      if (id === null) {
619	        const added = await firstValueFrom(
620	          this.http.post<Person>(this.url(sheet), { name, grade }, { headers: this.headers() }),
621	        );
622	        if (this.session.sheetId() !== sheet) return;
623	        this.people.update((list) => [...list, added]);
624	      } else {
625	        const saved = await firstValueFrom(
626	          this.http.put<Person>(`${this.url(sheet)}/${id}`, { name, grade, gradeFrom, version: this.editingVersion }, { headers: this.headers() }),
627	        );
628	        if (this.session.sheetId() !== sheet) return;
629	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
630	      }
631	      this.reset();
632	    } catch (e) {
633	      if (e instanceof HttpErrorResponse && e.status === 412 && id !== null) {
634	        await this.showCurrent(sheet, id);
635	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
636	        this.error.set('That name is already in use on this sheet.');
637	      } else {
638	        this.error.set(id === null ? 'Could not add that person.' : 'Could not save that person.');
639	      }
640	    } finally {
641	      this.saving = false;
642	    }
643	  }
644	
645	  /**
646	   * Add a DRAFT claim of the amount, dated the sheet's today with an empty note, for the person of
647	   * the name; one not on the sheet is added first with grade A. A refusal adds neither.
648	   */
649	  protected async quickAdd(): Promise<void> {
650	    if (this.quickAdding) return;
651	    this.quickError.set('');
652	    const sheet = this.session.sheetId();
653	    if (!sheet) return;
654	    const raw = this.quickForm.getRawValue();
655	    const name = raw.name.trim();
656	    const amount = raw.amount.trim();
657	    if (!name) {
658	      this.quickError.set('Enter a name.');
659	      return;
660	    }
661	    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount)) {
662	      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
663	      return;
664	    }
665	    this.quickAdding = true;
666	    try {
667	      const done = await firstValueFrom(
668	        this.http.post<QuickAdded>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, { headers: this.headers() }),
669	      );
670	      if (this.session.sheetId() !== sheet) return;
671	      if (done.added) this.people.update((list) => [...list.filter((p) => p.id !== done.person.id), done.person]);
672	      this.claimSaved(done.claim);
673	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
674	    } catch (e) {
675	      if (this.session.sheetId() !== sheet) return;
676	      this.quickError.set(
677	        e instanceof HttpErrorResponse && e.status === 423
678	          ? 'No claim dated inside a closed period can be changed.'
679	          : e instanceof HttpErrorResponse && e.status === 422
680	          ? RETIRED
681	          : e instanceof HttpErrorResponse && e.status === 409
682	          ? 'That name is already in use on this sheet.'
683	          : 'Could not quick-add that claim.',
684	      );
685	    } finally {
686	      this.quickAdding = false;
687	    }
688	  }
689	
690	  /** After a save refused as made from an old version: refuse it, and show the person as now stored. */
691	  private async showCurrent(sheet: string, id: number): Promise<void> {
692	    this.error.set('Someone else saved this person meanwhile; it now shows their values.');
693	    try {
694	      const list = await firstValueFrom(this.http.get<Person[]>(this.url(sheet), { headers: this.headers() }));
695	      if (this.session.sheetId() !== sheet) return;
696	      this.people.set(list);
697	      const current = list.find((p) => p.id === id);
698	      if (current && this.editingId() === id) {
699	        this.editingVersion = current.version;
700	        this.form.setValue({ name: current.name, grade: this.gradeOf(current), gradeFrom: '' }, { emitEvent: false });
701	      }
702	    } catch {
703	      // the error already shown stands
704	    }
705	  }
706	}
